-- Canonical Group Management Core schema. Existing legacy tables remain intact.\nCREATE TABLE IF NOT EXISTS gm_groups(group_id UUID PRIMARY KEY,telegram_chat_id BIGINT NOT NULL UNIQUE,chat_type VARCHAR(20) NOT NULL,title TEXT NOT NULL,username VARCHAR(255),description TEXT,telegram_owner_id BIGINT,is_forum BOOLEAN NOT NULL DEFAULT FALSE,telegram_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,first_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),last_seen_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_groups_chat_type_ck CHECK(chat_type IN ('group','supergroup')),CONSTRAINT gm_groups_title_ck CHECK(length(btrim(title))>0),CONSTRAINT gm_groups_metadata_ck CHECK(jsonb_typeof(telegram_metadata)='object'));\nCREATE UNIQUE INDEX IF NOT EXISTS gm_groups_username_uq ON gm_groups(username) WHERE username IS NOT NULL;\nCREATE INDEX IF NOT EXISTS gm_groups_updated_idx ON gm_groups(updated_at DESC,group_id DESC);\nCREATE TABLE IF NOT EXISTS gm_group_access(access_id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES gm_groups(group_id) ON DELETE RESTRICT,telegram_user_id BIGINT NOT NULL,role VARCHAR(20) NOT NULL,capabilities_override JSONB NOT NULL DEFAULT '{}'::jsonb,granted_by_user_id BIGINT,granted_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),revoked_by_user_id BIGINT,revoked_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_group_access_role_ck CHECK(role IN ('OWNER','ADMIN','OPERATOR')),CONSTRAINT gm_group_access_override_ck CHECK(jsonb_typeof(capabilities_override)='object'),CONSTRAINT gm_group_access_revoked_ck CHECK(revoked_at IS NULL OR revoked_at>=granted_at));\nCREATE UNIQUE INDEX IF NOT EXISTS gm_group_access_active_uq ON gm_group_access(group_id,telegram_user_id) WHERE revoked_at IS NULL;\nCREATE INDEX IF NOT EXISTS gm_group_access_user_idx ON gm_group_access(telegram_user_id);\nCREATE INDEX IF NOT EXISTS gm_group_access_group_role_idx ON gm_group_access(group_id,role);\nCREATE TABLE IF NOT EXISTS gm_group_registrations(registration_id UUID PRIMARY KEY,group_id UUID NOT NULL UNIQUE REFERENCES gm_groups(group_id) ON DELETE RESTRICT,status VARCHAR(20) NOT NULL DEFAULT 'UNREGISTERED',registered_by_user_id BIGINT,registered_at TIMESTAMPTZ,disabled_by_user_id BIGINT,disabled_at TIMESTAMPTZ,disable_reason TEXT,archived_at TIMESTAMPTZ,registration_version BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_registration_status_ck CHECK(status IN ('UNREGISTERED','REGISTERING','REGISTERED','DISABLED','ARCHIVED')),CONSTRAINT gm_registration_registered_at_ck CHECK(status<>'REGISTERED' OR registered_at IS NOT NULL),CONSTRAINT gm_registration_version_ck CHECK(registration_version>=1));\nCREATE TABLE IF NOT EXISTS gm_group_installations(installation_id UUID PRIMARY KEY,group_id UUID NOT NULL UNIQUE REFERENCES gm_groups(group_id) ON DELETE RESTRICT,status VARCHAR(20) NOT NULL DEFAULT 'NOT_INSTALLED',current_version INTEGER NOT NULL DEFAULT 0,target_version INTEGER,attempt_no INTEGER NOT NULL DEFAULT 0,started_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,failed_at TIMESTAMPTZ,failure_code VARCHAR(100),failure_message TEXT,installed_by_user_id BIGINT,config_version INTEGER NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_install_status_ck CHECK(status IN ('NOT_INSTALLED','PENDING','INSTALLING','INSTALLED','FAILED','UNINSTALLING','UNINSTALLED')),CONSTRAINT gm_install_version_ck CHECK(current_version>=0 AND (target_version IS NULL OR target_version>=1)),CONSTRAINT gm_install_attempt_ck CHECK(attempt_no>=0),CONSTRAINT gm_install_config_version_ck CHECK(config_version>=1));\nCREATE TABLE IF NOT EXISTS gm_group_runtime(runtime_id UUID PRIMARY KEY,group_id UUID NOT NULL UNIQUE REFERENCES gm_groups(group_id) ON DELETE RESTRICT,bot_membership_status VARCHAR(20) NOT NULL DEFAULT 'UNKNOWN',service_status VARCHAR(20) NOT NULL DEFAULT 'UNKNOWN',member_count INTEGER,admin_count INTEGER,last_message_at TIMESTAMPTZ,last_bot_activity_at TIMESTAMPTZ,last_admin_action_at TIMESTAMPTZ,last_security_event_at TIMESTAMPTZ,last_reconcile_at TIMESTAMPTZ,last_error_code VARCHAR(100),last_error_at TIMESTAMPTZ,runtime_revision BIGINT NOT NULL DEFAULT 1,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_runtime_bot_ck CHECK(bot_membership_status IN ('UNKNOWN','MEMBER','ADMINISTRATOR','RESTRICTED','LEFT','BANNED')),CONSTRAINT gm_runtime_service_ck CHECK(service_status IN ('UNKNOWN','ACTIVE','DEGRADED','PAUSED','STOPPED','BLOCKED')),CONSTRAINT gm_runtime_revision_ck CHECK(runtime_revision>=1));\nCREATE TABLE IF NOT EXISTS gm_group_permission_snapshots(snapshot_id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES gm_groups(group_id) ON DELETE RESTRICT,is_current BOOLEAN NOT NULL DEFAULT TRUE,membership_status VARCHAR(20) NOT NULL,is_anonymous BOOLEAN NOT NULL DEFAULT FALSE,can_manage_chat BOOLEAN NOT NULL DEFAULT FALSE,can_delete_messages BOOLEAN NOT NULL DEFAULT FALSE,can_manage_video_chats BOOLEAN NOT NULL DEFAULT FALSE,can_restrict_members BOOLEAN NOT NULL DEFAULT FALSE,can_promote_members BOOLEAN NOT NULL DEFAULT FALSE,can_change_info BOOLEAN NOT NULL DEFAULT FALSE,can_invite_users BOOLEAN NOT NULL DEFAULT FALSE,can_post_stories BOOLEAN NOT NULL DEFAULT FALSE,can_edit_stories BOOLEAN NOT NULL DEFAULT FALSE,can_delete_stories BOOLEAN NOT NULL DEFAULT FALSE,can_pin_messages BOOLEAN NOT NULL DEFAULT FALSE,can_manage_topics BOOLEAN NOT NULL DEFAULT FALSE,can_manage_tags BOOLEAN NOT NULL DEFAULT FALSE,can_send_welcome_messages BOOLEAN NOT NULL DEFAULT FALSE,can_be_edited BOOLEAN NOT NULL DEFAULT FALSE,custom_title TEXT,rights_json JSONB NOT NULL DEFAULT '{}'::jsonb,captured_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),source VARCHAR(30) NOT NULL DEFAULT 'telegram');\nCREATE UNIQUE INDEX IF NOT EXISTS gm_permission_current_uq ON gm_group_permission_snapshots(group_id) WHERE is_current=TRUE;\nCREATE TABLE IF NOT EXISTS gm_security_profiles(security_profile_id UUID PRIMARY KEY,profile_key VARCHAR(50) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,version INTEGER NOT NULL DEFAULT 1,config JSONB NOT NULL DEFAULT '{}'::jsonb,is_system BOOLEAN NOT NULL DEFAULT TRUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by_user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());\nCREATE TABLE IF NOT EXISTS gm_settings_profiles(settings_profile_id UUID PRIMARY KEY,profile_key VARCHAR(50) NOT NULL UNIQUE,display_name VARCHAR(100) NOT NULL,version INTEGER NOT NULL DEFAULT 1,config JSONB NOT NULL DEFAULT '{}'::jsonb,is_system BOOLEAN NOT NULL DEFAULT TRUE,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_by_user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());\nCREATE TABLE IF NOT EXISTS gm_group_settings(group_settings_id UUID PRIMARY KEY,group_id UUID NOT NULL UNIQUE REFERENCES gm_groups(group_id) ON DELETE RESTRICT,settings_profile_id UUID NOT NULL REFERENCES gm_settings_profiles(settings_profile_id) ON DELETE RESTRICT,settings_overrides JSONB NOT NULL DEFAULT '{}'::jsonb,config_version INTEGER NOT NULL DEFAULT 1,security_profile_key VARCHAR(50) NOT NULL DEFAULT 'default',updated_by_user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());\nCREATE TABLE IF NOT EXISTS gm_group_module_states(module_state_id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES gm_groups(group_id) ON DELETE RESTRICT,module_key VARCHAR(50) NOT NULL,state VARCHAR(20) NOT NULL DEFAULT 'READY',enabled BOOLEAN NOT NULL DEFAULT FALSE,version INTEGER NOT NULL DEFAULT 1,config_version INTEGER NOT NULL DEFAULT 1,last_error_code VARCHAR(100),last_error_at TIMESTAMPTZ,updated_by_user_id BIGINT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_module_unique UNIQUE(group_id,module_key),CONSTRAINT gm_module_state_ck CHECK(state IN ('READY','ACTIVE','DEGRADED','DISABLED','FAILED')));\nCREATE TABLE IF NOT EXISTS gm_group_resolution_attempts(resolution_id UUID PRIMARY KEY,request_id UUID NOT NULL UNIQUE,requester_user_id BIGINT NOT NULL,input_type VARCHAR(30) NOT NULL,normalized_reference TEXT,input_fingerprint BYTEA NOT NULL,resolved_group_id UUID REFERENCES gm_groups(group_id) ON DELETE RESTRICT,provider VARCHAR(40) NOT NULL,resolution_status VARCHAR(30) NOT NULL,access_state VARCHAR(30) NOT NULL,next_action VARCHAR(30),failure_code VARCHAR(100),metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());\nCREATE INDEX IF NOT EXISTS gm_resolution_requester_idx ON gm_group_resolution_attempts(requester_user_id,created_at DESC);\nCREATE TABLE IF NOT EXISTS gm_group_audit_log(audit_id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES gm_groups(group_id) ON DELETE RESTRICT,request_id UUID,actor_type VARCHAR(20) NOT NULL,actor_user_id BIGINT,source VARCHAR(20) NOT NULL,action VARCHAR(100) NOT NULL,target_type VARCHAR(50),target_id TEXT,before_data JSONB,after_data JSONB,result VARCHAR(20) NOT NULL,error_code VARCHAR(100),reason TEXT,metadata JSONB NOT NULL DEFAULT '{}'::jsonb,ip_address INET,user_agent TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_audit_actor_ck CHECK(actor_type<>'USER' OR actor_user_id IS NOT NULL),CONSTRAINT gm_audit_result_ck CHECK(result IN ('SUCCESS','FAILURE','DENIED','NOOP')));\nCREATE INDEX IF NOT EXISTS gm_audit_group_time_idx ON gm_group_audit_log(group_id,created_at DESC);\nCREATE INDEX IF NOT EXISTS gm_audit_actor_time_idx ON gm_group_audit_log(actor_user_id,created_at DESC);\nCREATE TABLE IF NOT EXISTS gm_domain_events(event_id UUID PRIMARY KEY,group_id UUID NOT NULL REFERENCES gm_groups(group_id) ON DELETE RESTRICT,event_type VARCHAR(100) NOT NULL,aggregate_version BIGINT NOT NULL,payload JSONB NOT NULL DEFAULT '{}'::jsonb,delivery_status VARCHAR(20) NOT NULL DEFAULT 'PENDING',attempt_count INTEGER NOT NULL DEFAULT 0,last_error TEXT,next_attempt_at TIMESTAMPTZ,published_at TIMESTAMPTZ,occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT gm_event_delivery_ck CHECK(delivery_status IN ('PENDING','PROCESSING','PUBLISHED','FAILED','DEAD')));\nCREATE INDEX IF NOT EXISTS gm_events_pending_idx ON gm_domain_events(next_attempt_at,created_at) WHERE delivery_status IN ('PENDING','FAILED');\nCREATE TABLE IF NOT EXISTS gm_idempotency_keys(idempotency_id UUID PRIMARY KEY,scope VARCHAR(50) NOT NULL,idempotency_key VARCHAR(255) NOT NULL,operation VARCHAR(100) NOT NULL,request_hash BYTEA NOT NULL,group_id UUID REFERENCES gm_groups(group_id) ON DELETE RESTRICT,actor_user_id BIGINT,status VARCHAR(20) NOT NULL DEFAULT 'PROCESSING',response_payload JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),expires_at TIMESTAMPTZ,completed_at TIMESTAMPTZ,CONSTRAINT gm_idempotency_status_ck CHECK(status IN ('PROCESSING','COMPLETED','FAILED','EXPIRED')));\nCREATE UNIQUE INDEX IF NOT EXISTS gm_idempotency_scope_key_uq ON gm_idempotency_keys(scope,idempotency_key);\n-- Backfill uses deterministic UUIDs so the migration can be rerun safely.\nINSERT INTO gm_groups(group_id,telegram_chat_id,chat_type,title,username,is_forum,created_at,updated_at) SELECT md5('gm:'||group_id::text)::uuid,group_id,CASE WHEN chat_type='group' THEN 'group' ELSE 'supergroup' END,COALESCE(NULLIF(title,''),'گروه بدون نام'),username,FALSE,COALESCE(created_at,NOW()),NOW() FROM owner_group_registry ON CONFLICT(telegram_chat_id) DO UPDATE SET title=EXCLUDED.title,username=EXCLUDED.username,updated_at=NOW();\nINSERT INTO gm_group_registrations(registration_id,group_id,status,registered_at) SELECT md5('reg:'||g.telegram_chat_id::text)::uuid,g.group_id,'REGISTERED',COALESCE(r.created_at,NOW()) FROM gm_groups g JOIN owner_group_registry r ON r.group_id=g.telegram_chat_id ON CONFLICT(group_id) DO NOTHING;\nINSERT INTO gm_group_installations(installation_id,group_id,status,current_version,completed_at,config_version) SELECT md5('inst:'||g.telegram_chat_id::text)::uuid,g.group_id,CASE WHEN COALESCE(bi.installed,FALSE) THEN 'INSTALLED' ELSE 'NOT_INSTALLED' END,CASE WHEN COALESCE(bi.installed,FALSE) THEN 1 ELSE 0 END,CASE WHEN COALESCE(bi.installed,FALSE) THEN COALESCE(bi.installed_at,NOW()) ELSE NULL END,1 FROM gm_groups g JOIN owner_group_registry r ON r.group_id=g.telegram_chat_id LEFT JOIN bot_group_installations bi ON bi.group_id=g.telegram_chat_id ON CONFLICT(group_id) DO NOTHING;\nINSERT INTO gm_security_profiles(security_profile_id,profile_key,display_name,config) VALUES(md5('security:default')::uuid,'default','پیش‌فرض','{"securityMode":"standard","audit":true}'),(md5('security:community')::uuid,'community','اجتماعی','{"securityMode":"standard","audit":true}'),(md5('security:strict')::uuid,'strict','سخت‌گیرانه','{"securityMode":"strict","audit":true}'),(md5('security:maximum')::uuid,'maximum_security','حداکثر امنیت','{"securityMode":"maximum","audit":true}') ON CONFLICT(profile_key) DO NOTHING;\nINSERT INTO gm_settings_profiles(settings_profile_id,profile_key,display_name,config) VALUES(md5('settings:default')::uuid,'default','پیش‌فرض','{"preset":"default"}'),(md5('settings:community')::uuid,'community','اجتماعی','{"preset":"community"}'),(md5('settings:strict')::uuid,'strict','سخت‌گیرانه','{"preset":"strict"}'),(md5('settings:maximum')::uuid,'maximum_security','حداکثر امنیت','{"preset":"maximum_security"}') ON CONFLICT(profile_key) DO NOTHING;\nINSERT INTO gm_group_settings(group_settings_id,group_id,settings_profile_id,security_profile_key) SELECT md5('settings:'||g.group_id::text)::uuid,g.group_id,sp.settings_profile_id,'default' FROM gm_groups g CROSS JOIN LATERAL(SELECT settings_profile_id FROM gm_settings_profiles WHERE profile_key='default' LIMIT 1) sp ON CONFLICT(group_id) DO NOTHING;\nINSERT INTO gm_group_runtime(runtime_id,group_id,bot_membership_status,service_status,member_count,admin_count,last_reconcile_at) SELECT md5('runtime:'||g.telegram_chat_id::text)::uuid,g.group_id,CASE WHEN r.telegram_status IN ('administrator','admin') THEN 'ADMINISTRATOR' WHEN r.telegram_status='member' THEN 'MEMBER' WHEN r.telegram_status='restricted' THEN 'RESTRICTED' WHEN r.telegram_status='left' THEN 'LEFT' WHEN r.telegram_status IN ('kicked','banned') THEN 'BANNED' ELSE 'UNKNOWN' END,CASE WHEN r.telegram_status IN ('left','kicked','banned') OR r.is_enabled=FALSE THEN 'STOPPED' WHEN r.bot_status IN ('ERROR','RESTRICTED') THEN 'DEGRADED' ELSE 'ACTIVE' END,r.member_count,r.admin_count,r.last_sync_at FROM gm_groups g JOIN owner_group_registry r ON r.group_id=g.telegram_chat_id ON CONFLICT(group_id) DO NOTHING;\nINSERT INTO gm_group_module_states(module_state_id,group_id,module_key,state,enabled) SELECT md5(m.module_key||':'||g.group_id::text)::uuid,g.group_id,m.module_key,CASE WHEN i.status='INSTALLED' THEN 'ACTIVE' ELSE 'READY' END,CASE WHEN i.status='INSTALLED' THEN TRUE ELSE FALSE END FROM gm_groups g JOIN gm_group_installations i ON i.group_id=g.group_id CROSS JOIN(VALUES('security'),('commands'),('statistics'),('members'),('activity'),('tools'))m(module_key) ON CONFLICT(group_id,module_key) DO NOTHING;